"use client";

import { CloudUpload } from "lucide-react";
import { useEffect, useId, useRef, useState } from "react";
import { cn } from "@/lib/utils";
import { UploadRow, type RowRenderer } from "./upload-row";
import { acceptedTypes, useUploadQueue, type UploadAccept, type UploadEntry, type UploadOptions } from "./upload-queue";

export { useUploadQueue, type UploadHandler, type UploadEntry, type UploadAccept } from "./upload-queue";

type ViewProps = {
  accept?: UploadAccept; className?: string; buttonClassName?: string; hint?: string;
  motion?: boolean; disabled?: boolean; renderRow?: RowRenderer;
};
export type UploadDropzoneProps = UploadOptions & ViewProps;

function summary(entries: UploadEntry[]) {
  const counts = { uploaded: 0, uploading: 0, failed: 0, rejected: 0 };
  for (const { status } of entries) counts[status]++;
  const parts: string[] = [];
  if (counts.uploaded) parts.push(`${counts.uploaded} ${counts.uploaded === 1 ? "file" : "files"} uploaded`);
  for (const status of ["uploading", "failed", "rejected"] as const) {
    if (counts[status]) parts.push(`${counts[status]} ${status}`);
  }
  return parts.join(" · ");
}

export function UploadDropzoneView({ entries, addFiles, retry, accept, className, buttonClassName, hint,
  motion = true, disabled, renderRow }: ReturnType<typeof useUploadQueue> & ViewProps) {
  const picker = useRef<HTMLInputElement>(null);
  const browse = useRef<HTMLButtonElement>(null);
  const root = useRef<HTMLElement>(null);
  const dragDepth = useRef(0);
  const [dragging, setDragging] = useState(false);
  const previousFailures = useRef(new Set<number>());
  const hintId = useId();
  const hasRows = entries.length > 0;

  useEffect(() => {
    const failed = entries.filter(row => row.status === "failed");
    const firstNew = failed.find(row => !previousFailures.current.has(row.id));
    previousFailures.current = new Set(failed.map(row => row.id));
    if (firstNew && document.activeElement === browse.current) {
      root.current?.querySelector<HTMLButtonElement>(`[data-retry="${firstNew.id}"]`)?.focus();
    }
  }, [entries]);

  function retryRow(id: number) {
    if (disabled) return;
    browse.current?.focus();
    retry(id);
  }

  return <section ref={root} aria-label="File uploads" className={cn("w-full min-w-0 rounded-xl border border-dashed border-border bg-background p-4 text-foreground",
    dragging && !disabled && "border-primary bg-primary/5", className)}
    onDragEnter={event => {
      if (!event.dataTransfer.types.includes("Files")) return;
      event.preventDefault();
      dragDepth.current++;
      setDragging(true);
    }}
    onDragLeave={event => {
      event.preventDefault();
      dragDepth.current = Math.max(0, dragDepth.current - 1);
      if (!dragDepth.current) setDragging(false);
    }}
    onDragOver={event => {
      if (!event.dataTransfer.types.includes("Files")) return;
      event.preventDefault();
      event.dataTransfer.dropEffect = disabled ? "none" : "copy";
    }}
    onDrop={event => {
      event.preventDefault();
      dragDepth.current = 0;
      setDragging(false);
      if (!disabled) addFiles(event.dataTransfer.files);
    }}>
    <input ref={picker} type="file" hidden multiple disabled={disabled} accept={acceptedTypes(accept).join(",") || undefined}
      onChange={event => {
        if (!disabled && event.target.files) addFiles(event.target.files);
        event.target.value = "";
      }} />
    <div className={cn("flex gap-2", hasRows ? "flex-wrap items-center justify-between" : "flex-col items-center py-4 text-center")}>
      {!hasRows && <><span className="grid size-10 place-items-center rounded-full bg-muted text-muted-foreground">
        <CloudUpload aria-hidden="true" className="size-5" /></span>
        <p className="text-sm font-medium">{dragging ? "Drop to add files" : "Drop files to upload"}</p></>}
      <p role="status" aria-atomic="true" className={cn("text-lg font-semibold leading-tight", !hasRows && "sr-only")}>{summary(entries)}</p>
      <button ref={browse} type="button" disabled={disabled} aria-describedby={hint ? hintId : undefined} onClick={() => picker.current?.click()}
        className={cn("min-h-9 rounded-md bg-primary px-3 text-sm font-medium text-primary-foreground focus-visible:outline focus-visible:outline-1 disabled:opacity-50", buttonClassName)}>
        {hasRows ? "Add more files" : "Browse files"}
      </button>
    </div>
    {hasRows && <ul aria-label="Files" className="mt-3 grid max-h-80 min-w-0 gap-1.5 overflow-y-auto">
      {entries.map(entry => <UploadRow key={entry.id} entry={entry} motion={motion} disabled={disabled} retry={retryRow} renderRow={renderRow} />)}
    </ul>}
    {hint && <p id={hintId} className={cn("text-xs text-muted-foreground", hasRows ? "mt-3" : "mt-2 text-center")}>{hint}</p>}
  </section>;
}

export function UploadDropzone({ upload, maxFiles, ...props }: UploadDropzoneProps) {
  const queue = useUploadQueue({ upload, maxFiles, accept: props.accept });
  return <UploadDropzoneView {...props} {...queue} />;
}

"use client";

import { useEffect, useRef, useState } from "react";

export type UploadHandler = (file: File, onProgress: (fraction: number) => void, signal: AbortSignal) => Promise<void>;
export type UploadAccept = Record<string, readonly string[]>;
export type UploadEntry = {
  id: number;
  name: string;
  size: number;
  status: "uploading" | "uploaded" | "failed" | "rejected";
  progress?: number;
  message?: string;
};
export type UploadOptions = { upload: UploadHandler; accept?: UploadAccept; maxFiles?: number };

export function acceptedTypes(accept?: UploadAccept) {
  return Object.entries(accept ?? {}).flatMap(([mime, extensions]) => [mime, ...extensions])
    .map(token => token.trim().toLowerCase()).filter(Boolean);
}

function accepts(file: File, types: string[]) {
  return !types.length || types.some(type => {
    if (type.startsWith(".")) return file.name.toLowerCase().endsWith(type);
    if (type.endsWith("/*")) return file.type.toLowerCase().startsWith(type.slice(0, -1));
    return file.type.toLowerCase() === type;
  });
}

/** The upload callback supplies the transfer. Only failed files are kept for retry. */
export function useUploadQueue({ upload, accept, maxFiles = Infinity }: UploadOptions) {
  const [entries, setEntries] = useState<UploadEntry[]>([]);
  const nextId = useRef(0);
  const attempts = useRef(new Map<number, AbortController>());
  const failures = useRef(new Map<number, File>());
  useEffect(() => {
    const requests = attempts.current;
    const failed = failures.current;
    return () => {
      for (const controller of requests.values()) controller.abort();
      requests.clear();
      failed.clear();
    };
  }, []);

  function update(id: number, patch: Partial<UploadEntry>) {
    setEntries(rows => rows.map(row => row.id === id ? { ...row, ...patch } : row));
  }

  async function run(id: number, file: File) {
    const controller = new AbortController();
    attempts.current.set(id, controller);
    try {
      await upload(file, fraction => {
        if (attempts.current.get(id) !== controller || !Number.isFinite(fraction)) return;
        update(id, { progress: Math.max(0, Math.min(1, fraction)) });
      }, controller.signal);
      if (!controller.signal.aborted) update(id, { status: "uploaded", progress: 1 });
    } catch (error) {
      if (!controller.signal.aborted) {
        failures.current.set(id, file);
        update(id, { status: "failed", message: error instanceof Error && error.message ? error.message : "Upload failed." });
      }
    } finally {
      attempts.current.delete(id);
    }
  }

  function addFiles(files: Iterable<File>) {
    const types = acceptedTypes(accept);
    const batch: UploadEntry[] = [];
    const pending: { id: number; file: File }[] = [];
    for (const file of files) {
      const id = ++nextId.current;
      let message: string | undefined;
      if (!accepts(file, types)) message = "File type isn’t accepted.";
      else if (pending.length >= maxFiles) message = `Limit is ${maxFiles} per selection.`;
      batch.push({ id, name: file.name, size: file.size, status: message ? "rejected" : "uploading", message });
      if (!message) pending.push({ id, file });
    }
    if (batch.length) setEntries(rows => [...rows, ...batch]);
    for (const { id, file } of pending) void run(id, file);
  }

  function retry(id: number) {
    const file = failures.current.get(id);
    if (!file) return;
    failures.current.delete(id);
    update(id, { status: "uploading", message: undefined, progress: undefined });
    void run(id, file);
  }
  return { entries, addFiles, retry };
}

"use client";

import type { ReactNode } from "react";
import { Check, FileText, RotateCcw } from "lucide-react";
import { cn } from "@/lib/utils";
import type { UploadEntry } from "./upload-queue";

export type RowRenderer = (entry: UploadEntry, retry: () => void) => ReactNode;

export function UploadRow({ entry, retry, motion, disabled, renderRow }: {
  entry: UploadEntry; retry: (id: number) => void; motion: boolean; disabled?: boolean; renderRow?: RowRenderer;
}) {
  const { id, name, status, progress, message } = entry;
  const percent = progress === undefined ? undefined : Math.round(progress * 100);
  if (renderRow) return <li data-status={status}>{renderRow(entry, () => retry(id))}</li>;
  return <li data-status={status} className="grid gap-1.5 rounded-md bg-border/65 px-3 py-2.5 dark:bg-muted/65">
    <div className="flex min-w-0 items-center gap-2">
      <FileText aria-hidden="true" className="size-4 shrink-0 text-muted-foreground" />
      <span title={name} className="min-w-0 flex-1 truncate text-sm font-medium">{name}</span>
      {status === "uploaded" && <>
        <Check aria-hidden="true" className="size-4 shrink-0 text-muted-foreground" />
        <span className="sr-only">Uploaded</span>
      </>}
      {status === "uploading" && <span className="text-xs tabular-nums text-muted-foreground">{percent === undefined ? "Uploading…" : `${percent}%`}</span>}
      {status === "failed" && <button type="button" data-retry={id} disabled={disabled} aria-label={`Retry ${name}`} title="Retry upload" onClick={() => retry(id)}
        className="grid size-8 shrink-0 place-items-center rounded-md hover:bg-muted focus-visible:outline focus-visible:outline-2 focus-visible:outline-ring">
        <RotateCcw aria-hidden="true" className="size-4" />
      </button>}
    </div>
    {message && <p className="break-words text-xs text-destructive">{message}</p>}
    {status === "uploading" && <div role="progressbar" aria-label={`Upload progress for ${name}`}
      aria-valuemin={0} aria-valuemax={100} aria-valuenow={percent}
      className="h-1.5 overflow-hidden rounded-full bg-foreground/10">
      <div className={cn("h-full rounded-full bg-primary",
        percent === undefined && "w-1/3", motion && (percent === undefined ? "motion-safe:animate-pulse" : "motion-safe:transition-[width]"))}
        style={percent !== undefined ? { width: `${percent}%` } : undefined} />
    </div>}
  </li>;
}
